import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { skeletonClassesByShape } from "./view";
import type { SkeletonShape } from "./view";

export type { SkeletonShape };

export { skeletonBaseClasses, skeletonClassesByShape } from "./view";

export type ViewConfig = Readonly<{
  shape?: SkeletonShape;
  classes?: string;
}>;

export const view = <ParentMessage>({
  shape = "Block",
  classes,
}: ViewConfig = {}): Html => {
  const h = html<ParentMessage>();
  const cn = [skeletonClassesByShape(shape), classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.span([h.Class(cn), h.AriaHidden(true)], []);
};

export type SkeletonShape = "Text" | "Avatar" | "Button" | "Block";

export const skeletonBaseClasses = "animate-pulse rounded-md bg-gray-200";

export const skeletonClassesByShape = (
  shape: SkeletonShape = "Block"
): string => {
  if (shape === "Text") {
    return `${skeletonBaseClasses} h-4 w-40`;
  }

  if (shape === "Avatar") {
    return `${skeletonBaseClasses} h-10 w-10 rounded-full`;
  }

  if (shape === "Button") {
    return `${skeletonBaseClasses} h-9 w-24`;
  }

  return `${skeletonBaseClasses} h-28 w-full`;
};

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Skeleton from "./index";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [],
    [
      h.span([], ["Loading placeholder"]),
      Skeleton.view({ shape: "Avatar" }),
      Skeleton.view({ shape: "Text" }),
      Skeleton.view({ shape: "Button" }),
      Skeleton.view({ shape: "Block" }),
    ]
  );
};

describe("Skeleton registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Loading placeholder")).toExist()
    );
  });
});
